@startuml

class HospitalHouseMD {
  + name : string
}

class Patient {
  + name : string
  + id : string
}

class Doctor {
  + name : string
  + practitionerNumber : int
}

class HeadDoctor {
  + name : string
}

class Diagnosis {
  + description : string
  + date : date
}

class Treatment {
  + name : string
  + description : string
}

class TreatmentStage {
  + level : int
}

enum PriorityScore {
  High
  Low
}

class Illness {
  + name : string
  + priority : PriorityScore
}

class ConsentForm {
  + signature : string
  + date : date
}

class TreatmentRecord {
  + dateStarted : date
  + dateEnded : date
}

Doctor "1..*" -- "0..*" Patient : treats
Doctor "1" -- "0..*" Diagnosis : makes
HeadDoctor --|> Doctor
HeadDoctor "1" -- "0..*" Diagnosis : approves
HospitalHouseMD "1" *-- "1..*" Treatment
Diagnosis "1" -- "0..*" Treatment : applicableTo
Patient "1" -- "1..*" TreatmentRecord
TreatmentRecord "1" *-- "1" Treatment
TreatmentRecord "1" *-- "1" Diagnosis
TreatmentRecord "1" *-- "1" Patient
TreatmentRecord "1" -- "1" TreatmentStage
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "0..*" TreatmentRecord
Illness "1" -- "0..*" Diagnosis
Illness "1" -- "0..*" Treatment

@enduml

